"""Fixed-point counts of the landmark ECA rules over GF(2)."""
from __future__ import annotations
from itertools import product
from typing import Callable, Tuple

LocalRule = Callable[[int, int, int], int]

def step(g: LocalRule, s: Tuple[int, ...]) -> Tuple[int, ...]:
    n = len(s)
    return tuple(g(s[(i - 1) % n], s[i], s[(i + 1) % n]) for i in range(n))

def fixed_count(g: LocalRule, n: int) -> int:
    return sum(1 for s in product((0, 1), repeat=n) if step(g, s) == s)

rules = {
    "Rule 0":   lambda a, b, c: 0,
    "Rule 204": lambda a, b, c: b,
    "Rule 90":  lambda a, b, c: (a + c) % 2,
    "Rule 150": lambda a, b, c: (a + b + c) % 2,
    "Rule 110": lambda a, b, c: (b + c + b * c + a * b * c) % 2,
}
for name, g in rules.items():
    print(name, [fixed_count(g, n) for n in range(2, 9)])

