"""Rule 90 fixed-point dimension follows the Pisano period 3."""
from __future__ import annotations
from itertools import product

def step90(s):
    n = len(s)
    return tuple((s[(i - 1) % n] + s[(i + 1) % n]) % 2 for i in range(n))

def dim90(n: int) -> int:
    count = sum(1 for s in product((0, 1), repeat=n) if step90(s) == s)
    return count.bit_length() - 1  # count is a power of two (linear variety)

for n in range(2, 13):
    print(f"n={n:2d}  3|n={n % 3 == 0!s:5}  dim V90 = {dim90(n)}")

"""Test whether each variety is a linear subspace of GF(2)^n."""
from __future__ import annotations
from itertools import product
from typing import Callable, Tuple

def step(g, s):
    n = len(s)
    return tuple(g(s[(i - 1) % n], s[i], s[(i + 1) % n]) for i in range(n))

def is_linear(g, n: int) -> bool:
    fixed = {s for s in product((0, 1), repeat=n) if step(g, s) == s}
    if tuple([0] * n) not in fixed:
        return False
    return all(tuple((x[i] + y[i]) % 2 for i in range(n)) in fixed
               for x in fixed for y in fixed)

rules = {
    "Rule 90 (additive)":  lambda a, b, c: (a + c) % 2,
    "Rule 150 (additive)": lambda a, b, c: (a + b + c) % 2,
    "Rule 110 (cubic)":    lambda a, b, c: (b + c + b * c + a * b * c) % 2,
}
for name, g in rules.items():
    print(f"{name:22s} linear? {is_linear(g, 6)}")

