from __future__ import annotations
from typing import Dict, FrozenSet, Tuple

def multilinear_gf2(code: int) -> Tuple[Dict[FrozenSet[str], int], int]:
    """Recover the multilinear GF(2) polynomial of an ECA from its Wolfram code."""
    vars_ = ("a", "b", "c")  # a=left(bit2), b=cell(bit1), c=right(bit0)
    truth: Dict[Tuple[int, int, int], int] = {}
    for a in (0, 1):
        for b in (0, 1):
            for c in (0, 1):
                idx = a * 4 + b * 2 + c
                truth[(a, b, c)] = (code >> idx) & 1
    coeff: Dict[FrozenSet[str], int] = {}
    subsets = [frozenset(), frozenset("a"), frozenset("b"), frozenset("c"),
               frozenset("ab"), frozenset("ac"), frozenset("bc"), frozenset("abc")]
    for S in subsets:
        acc = 0
        for (a, b, c), val in truth.items():
            on = {v for v, x in zip(vars_, (a, b, c)) if x == 1}
            if on <= S:
                acc ^= val
        if acc:
            coeff[S] = 1
    degree = max((len(S) for S in coeff), default=0)
    return coeff, degree

if __name__ == "__main__":
    for code in (0, 90, 110, 150, 204):
        c, d = multilinear_gf2(code)
        terms = "+".join("".join(sorted(s)) or "1" for s in c) or "0"
        print(f"Rule {code:3d}: g = {terms}   (degree {d})")

from __future__ import annotations
from itertools import product
from typing import Callable, List, Tuple

LocalRule = Callable[[int, int, int], int]

def fixed_variety(g: LocalRule, n: int) -> List[Tuple[int, ...]]:
    """Return all configurations in GF(2)^n fixed by g on a cycle of length n."""
    out: List[Tuple[int, ...]] = []
    for s in product((0, 1), repeat=n):
        if all(g(s[(i - 1) % n], s[i], s[(i + 1) % n]) == s[i] for i in range(n)):
            out.append(s)
    return out

if __name__ == "__main__":
    rule110 = lambda a, b, c: (b + c + b * c + a * b * c) % 2
    for n in range(2, 7):
        print(f"n={n}: V(110) = {fixed_variety(rule110, n)}")

